use axum::{extract::State,http::{HeaderMap,StatusCode},response::IntoResponse,routing::{get,post},Json,Router};
use base64::Engine;
use hmac::{Hmac,Mac};
use reqwest::Client;
use serde::{Deserialize,Serialize};
use sha2::Sha256;
use std::{process::Command,sync::Arc};
use tokio::sync::RwLock;

type H=Hmac<Sha256>;type S=Arc<RwLock<C>>;
#[derive(Clone,Deserialize)]struct C{#[serde(default=bind)]bind:String,shared_secret:String,#[serde(default=ollama)]ollama_url:String,#[serde(default=vision)]vision_model:String,#[serde(default=ha)]home_assistant_url:String,#[serde(default)]home_assistant_token:String,#[serde(default)]admin_actions:Vec<String>,#[serde(default=agent)]trusted_agent:String,#[serde(default)]trusted_agent_may_authorize_admin:bool}
fn bind()->String{"127.0.0.1:8790".into()}fn ollama()->String{"http://192.168.10.181:11434".into()}fn vision()->String{"llava:latest".into()}fn ha()->String{"http://homeassistant.local:8123".into()}fn agent()->String{"jonathan".into()}
#[derive(Deserialize)]struct V{image_base64:String,#[serde(default)]prompt:String,#[serde(default= mime)]mime_type:String}fn mime()->String{"image/png".into()}
#[derive(Serialize)]struct VM{role:String,content:String,images:Vec<String>}#[derive(Serialize)]struct VB{model:String,messages:Vec<VM>,stream:bool}#[derive(Deserialize)]struct VR{message:VA}#[derive(Deserialize)]struct VA{content:String}
#[derive(Deserialize,Serialize)]struct HA{domain:String,service:String,#[serde(default)]data:serde_json::Value}
#[derive(Deserialize,Serialize)]struct AR{name:String,source:String,#[serde(default)]elevated:bool}
#[tokio::main]async fn main()->anyhow::Result<()>{let p=std::env::args().nth(1).unwrap_or("/etc/jimmy/config.toml".into());let c: C=toml::from_str(&tokio::fs::read_to_string(p).await?)?;if c.shared_secret.len()<32{anyhow::bail!("shared_secret too short")};let b=c.bind.clone();let s=Arc::new(RwLock::new(c));let r=Router::new().route("/health",get(health)).route("/v1/vision/analyze",post(vision_api)).route("/v1/homeassistant/states",get(states)).route("/v1/homeassistant/service",post(service)).route("/v1/admin/action",post(admin)).with_state(s);axum::serve(tokio::net::TcpListener::bind(b).await?,r).await?;Ok(())}
async fn health()->impl IntoResponse{Json(serde_json::json!({"ok":true,"service":"jimmy-backend","version":"0.3.0"}))}
async fn auth(s:&S,h:&HeaderMap,b:&[u8])->anyhow::Result<()>{let sig=h.get("x-jimmy-signature").and_then(|v|v.to_str().ok()).unwrap_or("");let sec=s.read().await.shared_secret.clone();let mut m=H::new_from_slice(sec.as_bytes())?;m.update(b);let e=hex::encode(m.finalize().into_bytes());if sig.len()!=e.len(){anyhow::bail!("invalid signature")};let mut d=0u8;for(a,b)in sig.as_bytes().iter().zip(e.as_bytes()){d|=a^b}if d!=0{anyhow::bail!("invalid signature")}Ok(())}fn bad(e:anyhow::Error)->axum::response::Response{(StatusCode::UNAUTHORIZED,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()}
async fn vision_api(State(s):State<S>,h:HeaderMap,Json(q):Json<V>)->impl IntoResponse{let p=serde_json::to_vec(&q).unwrap_or_default();if let Err(e)=auth(&s,&h,&p).await{return bad(e)}if q.image_base64.len()>20_000_000{return (StatusCode::PAYLOAD_TOO_LARGE,Json(serde_json::json!({"ok":false,"error":"image too large"}))).into_response()}let bytes=match base64::engine::general_purpose::STANDARD.decode(q.image_base64){Ok(x)=>x,Err(_)=>return (StatusCode::BAD_REQUEST,Json(serde_json::json!({"ok":false,"error":"invalid base64"}))).into_response()};let c=s.read().await.clone();let image=base64::engine::general_purpose::STANDARD.encode(bytes);let prompt=if q.prompt.is_empty(){"Describe this image accurately. If it is a desktop screenshot, identify visible apps, windows, dialogs and errors.".into()}else{q.prompt};let body=VB{model:c.vision_model.clone(),stream:false,messages:vec![VM{role:"user".into(),content:prompt,images:vec![format!("data:{};base64,{}",q.mime_type,image)]}]};match Client::new().post(format!("{}/api/chat",c.ollama_url.trim_end_matches('/'))).json(&body).send().await{Ok(r)if r.status().is_success()=>match r.json::<VR>().await{Ok(v)=>Json(serde_json::json!({"ok":true,"model":c.vision_model,"description":v.message.content})).into_response(),Err(e)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()},Ok(r)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":format!("vision backend returned {}",r.status())}))).into_response(),Err(e)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()}}
async fn states(State(s):State<S>,h:HeaderMap)->impl IntoResponse{if let Err(e)=auth(&s,&h,b"ha-states").await{return bad(e)}let c=s.read().await.clone();if c.home_assistant_token.is_empty(){return (StatusCode::SERVICE_UNAVAILABLE,Json(serde_json::json!({"ok":false,"error":"Home Assistant token not configured"}))).into_response()}match Client::new().get(format!("{}/api/states",c.home_assistant_url.trim_end_matches('/'))).bearer_auth(c.home_assistant_token).send().await{Ok(r)if r.status().is_success()=>Json(serde_json::json!({"ok":true,"states":r.json::<serde_json::Value>().await.unwrap_or_default()})).into_response(),Ok(r)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":r.status().to_string()}))).into_response(),Err(e)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()}}
async fn service(State(s):State<S>,h:HeaderMap,Json(q):Json<HA>)->impl IntoResponse{let p=serde_json::to_vec(&q).unwrap_or_default();if let Err(e)=auth(&s,&h,&p).await{return bad(e)}if !safe(&q.domain)||!safe(&q.service){return (StatusCode::BAD_REQUEST,Json(serde_json::json!({"ok":false,"error":"invalid service"}))).into_response()}let c=s.read().await.clone();if c.home_assistant_token.is_empty(){return (StatusCode::SERVICE_UNAVAILABLE,Json(serde_json::json!({"ok":false,"error":"Home Assistant token not configured"}))).into_response()}match Client::new().post(format!("{}/api/services/{}/{}",c.home_assistant_url.trim_end_matches('/'),q.domain,q.service)).bearer_auth(c.home_assistant_token).json(&q.data).send().await{Ok(r)if r.status().is_success()=>Json(serde_json::json!({"ok":true})).into_response(),Ok(r)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":r.status().to_string()}))).into_response(),Err(e)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()}}
async fn admin(State(s):State<S>,h:HeaderMap,Json(q):Json<AR>)->impl IntoResponse{let p=serde_json::to_vec(&q).unwrap_or_default();if let Err(e)=auth(&s,&h,&p).await{return bad(e)}let c=s.read().await.clone();if !c.admin_actions.iter().any(|x|x==&q.name)||!q.elevated||q.source!=c.trusted_agent||!c.trusted_agent_may_authorize_admin{return (StatusCode::FORBIDDEN,Json(serde_json::json!({"ok":false,"error":"trusted agent authorization denied"}))).into_response()}match Command::new("sudo").args(["-n","/usr/local/libexec/jimmy-admin",&q.name]).output(){Ok(o)if o.status.success()=>Json(serde_json::json!({"ok":true,"action":q.name})).into_response(),Ok(o)=>(StatusCode::BAD_REQUEST,Json(serde_json::json!({"ok":false,"error":String::from_utf8_lossy(&o.stderr)}))).into_response(),Err(e)=>(StatusCode::BAD_GATEWAY,Json(serde_json::json!({"ok":false,"error":e.to_string()}))).into_response()}}
fn safe(x:&str)->bool{!x.is_empty()&&x.len()<65&&x.bytes().all(|b|b.is_ascii_alphanumeric()||b==b'_'||b==b'-')}
